import { fetchBaseQuery, } from '@reduxjs/toolkit/query/react';
import { LS_ACCESS_TOKEN } from '06_shared/constants/localStorage';
import { API_VERSION_PREFIX } from '06_shared/constants/api';
const baseUrl = `${__API_URL__}${API_VERSION_PREFIX}`;
/**
 * Logs out the user by clearing the stored access token.
 */
const logout = async () => {
    localStorage.removeItem(LS_ACCESS_TOKEN);
};
/**
 * Fetches a new access token using the refresh token.
 */
const fetchWithTimeout = async (url, options, timeout = 5000) => {
    return new Promise((resolve, reject) => {
        const timer = setTimeout(() => reject(new Error('Timeout')), timeout);
        fetch(url, options)
            .then((response) => {
            clearTimeout(timer);
            resolve(response);
        })
            .catch((error) => {
            clearTimeout(timer);
            reject(error);
        });
    });
};
const fetchNewAccessToken = async () => {
    try {
        const response = await fetchWithTimeout(`${baseUrl}/auth/refresh`, {
            method: 'POST',
            credentials: 'include',
            headers: {
                'Content-Type': 'application/json',
            },
        });
        if (!response.ok) {
            console.error(`Token error: ${response.status}`);
            return null;
        }
        return await response.json();
    }
    catch (error) {
        console.error('Network error:', error);
        return null;
    }
};
/**
 * Creates a base query function with optional authorization headers.
 */
const createBaseQuery = (accessToken) => fetchBaseQuery({
    baseUrl,
    credentials: 'include',
    prepareHeaders: (headers) => {
        if (accessToken) {
            headers.set('authorization', accessToken);
        }
        return headers;
    },
});
/**
 * Base query function with token refresh handling.
 */
const baseQuery = async (args, api, extraOptions) => {
    const accessToken = localStorage.getItem(LS_ACCESS_TOKEN);
    let result = await createBaseQuery(accessToken)(args, api, extraOptions);
    // Backend maps every access-token failure (missing/invalid/expired) to 403, not 401.
    if (result.error?.status === 401 || result.error?.status === 403) {
        const newTokenData = await fetchNewAccessToken();
        const accessToken = newTokenData?.result?.access_token
            ? `${newTokenData.result.token_type} ${newTokenData.result.access_token}`
            : null;
        if (accessToken) {
            localStorage.setItem(LS_ACCESS_TOKEN, accessToken);
            result = await createBaseQuery(accessToken)(args, api, extraOptions);
        }
        else {
            await logout();
        }
    }
    return result;
};
export { baseUrl, baseQuery };
