import { createSlice } from '@reduxjs/toolkit';
const initialState = {
    information: undefined,
};
export const bitcoinPublicSlice = createSlice({
    name: 'bitcoinPublic',
    initialState,
    reducers: {
        setBitcoinPublicInformation: (state, action) => {
            state.information = action.payload;
        },
        resetBitcoinPublicSlice() {
            return initialState;
        },
    }
});
export const { actions: bitcoinPublicActions } = bitcoinPublicSlice;
export const { reducer: bitcoinPublicReducer } = bitcoinPublicSlice;
